@startuml

class User {
  + name
  + surname
}

class Subscriber extends User {
  + phone
  + address
  + credit
}

class MovieShop {
  + listMovies()
  + order()
  + subscribe()
}

class Order {
  + date
}

class Movie {
  + name
  + type
}

class MovieRent {
  + status
  + loanDate
  + price
}

class MovieOrder {
  + date
}

User "*" --> "1" MovieShop : uses
MovieShop "1" --> "*" Order : make
MovieShop "1" o-- "*" Movie
Subscriber "*" --> "1..*" MovieRent : hire
User "1" -- "*" Order : places
User "1" -- "*" MovieOrder : places
Movie "1" -- "*" MovieOrder : is ordered
Movie "1" -- "*" MovieRent : is rented

@enduml

